+// A custom streambuf to intercept and filter std::cout messages
+class FilterBuf : public std::streambuf {
+public:
+    FilterBuf(std::streambuf* original_buf) : original_buf_(original_buf) {}
+
+protected:
+    int overflow(int c) override {
+        if (c == EOF) return EOF;
+        buffer_ += static_cast<char>(c);
+        if (c == '\n') {
+            std::string line = buffer_;
+            // Replace patterns like Circle(2.0) with Circle(r), etc.
+            line = std::regex_replace(line, std::regex(R"(Circle\(\s*[-+]?[0-9]*\.?[0-9]+(\s*[eE][-+]?[0-9]+)?\s*\))"), "Circle(r)\n");
