+            
+            original_buf_->sputn(line.c_str(), line.size());
+            buffer_.clear();
+        }
+        return c;
+    }
+
+    int sync() override {
+        if (!buffer_.empty()) {
+            original_buf_->sputn(buffer_.c_str(), buffer_.size());
+            buffer_.clear();
+        }
+        return original_buf_->sync();
+    }
+
+private:
+    std::streambuf* original_buf_;
+    std::string buffer_;
+};

